public static MobCarts Find(MobCartID _cartId, boolean _selectForUpdate = false)
{
    MobCarts carts;

    carts.selectForUpdate(_selectForUpdate);
    select firstonly carts where carts.CartID == _cartId;
    return carts;
}

public static MobCarts FindByLocation(InventLocationId _locId, WMSLocationId _wmsLoc, boolean _selectForUpdate = false)
{
    MobCarts carts;

    carts.selectForUpdate(_selectForUpdate);
    select firstonly carts where carts.InventLocationId == _locId && carts.WMSLocationId == _wmsLoc;
    return carts;
}

public static MobCarts FindOrCreate(MobCartID _cartId, InventLocationId _locId, WMSLocationId _wmsLoc)
{
    MobCarts carts;

    ttsbegin;
    select firstonly forupdate carts where carts.CartID == _cartId;

    carts.CartID = _cartId;
    carts.InventLocationId = _locId;
    carts.WMSLocationId = _wmsLoc;
    carts.InventSiteId = InventLocation::find(_locId).InventSiteId;

    carts.write();
    ttscommit;
    return carts;
}

/// <summary>
///
/// </summary>
public static MobCarts addLicensePlate(MobCartID _cartId)
{
    MobCarts carts;
    NumberSeq		num = NumberSeq::newGetNum(WHSParameters::numRefWHSLicensePlateId());

    ttsbegin;
    carts = MobCarts::Find(_cartId,true);
    carts.WhsLicensePlateId = num.num();

    num.used(); // mark the number as used
    carts.update();
    WHSLicensePlate::createLicensePlate(carts.WhsLicensePlateId);
    ttscommit;
    return carts;
}

